"""Editorial source: each beat has one equation, explanation and optional motion."""
CHAPTERS=[]
def chapter(title,diagram=''):
    CHAPTERS.append({'title':title,'diagram':diagram,'beats':[]})
def b(tex,caption,action='',hold=0):
    CHAPTERS[-1]['beats'].append({'tex':tex,'caption':caption,'action':action,'hold':hold})

chapter('Why the equations work','roadmap')
b(r"C'\stackrel{?}{=}C",'ML-KEM decapsulation recomputes a ciphertext.\nIt checks that result against the ciphertext it received.')
b(r'x_i=(x_{i1}+x_{i2}+x_{i3})\bmod3329','PAMS receives three arithmetic shares of each coefficient.\nTogether, they represent the number we want to check.')
b(r'\operatorname{Compress}_d(x_i)\stackrel{?}{=}c_i','Would that number compress to the expected public value?\nThis is the question for one coefficient.')
b(r'b^{(i)}=[Z_i<\Theta_{c_i}]','PAMS instead makes this comparison. Brackets mean\n1 when the statement is true, and 0 when it is false.')
b(r'Z_i=\left(\sum_{j=1}^{3}F_{14}(x_{ij})+2-F_{14}(a_{c_i})\right)\bmod2^{14}','The share transforms, the added two, and the starting boundary\ncombine to give the position called Z.',hold=9)
b(r'\Theta_{c_i}=\left(F_{14}(a_{c_i+1})-F_{14}(a_{c_i})-1\right)\bmod2^{14}','Theta is the comparison threshold.\nIt comes from the two boundaries of the expected interval.',hold=9)
b(r'F_{14}(t)=\left\lfloor\frac{2^{14}t}{3329}\right\rfloor','F scales a number and rounds down.\nWe will explain why these definitions give the right answer.','roadmap')

chapter('1. Flooring before adding changes the answer','floor')
b(r'\lfloor2.8+3.7+4.9\rfloor=\lfloor11.4\rfloor=11','Add first: the fractional pieces contribute to the sum.\nOnly the final 0.4 is discarded.')
b(r'\lfloor2.8\rfloor+\lfloor3.7\rfloor+\lfloor4.9\rfloor=2+3+4=9','Floor first: each number loses its own fractional piece.\nWatch those three pieces fall away.','discard')
b(r'0.8+0.7+0.9=2.4','Those discarded pieces contained two whole units\nas well as the final fraction.','collect')
b(r'11-9=2','That is why the two orders give different answers.\nFlooring is not interchangeable with addition.')
b(r'\sum_{j=1}^{3}F_{14}(x_{ij})\ \stackrel{?}{=}\ F_{14}\!\left(\sum_{j=1}^{3}x_{ij}\right)','PAMS transforms the shares separately.\nWe need to bound the information lost by doing that.',hold=9)

chapter('Separate the whole and fractional parts','split')
b(r'0\le x_{ij}<3329,\qquad x_{ij}\in\mathbb Z,\qquad j=1,2,3','We use canonical shares: whole numbers from 0 to 3328.\nThe share index j is 1, 2, or 3.')
b(r'y_{ij}:=\frac{2^{14}x_{ij}}{3329}','Call the scaled share y.\nAt this stage we have not rounded anything down.')
b(r'w_{ij}:=\lfloor y_{ij}\rfloor=F_{14}(x_{ij})','Call its whole-number part w.\nThis is exactly the transform PAMS calculates.')
b(r'f_{ij}:=y_{ij}-\lfloor y_{ij}\rfloor','Call the leftover fractional part f.\nSubtracting the whole part leaves only that remainder.')
b(r'4.7=4+0.7','For example, 4.7 separates into 4 and 0.7.\nThe same separation works for each of the three shares.','split')
b(r'y_{ij}=w_{ij}+f_{ij},\qquad 0\le f_{ij}<1','Every fractional part is at least zero and less than one.\nA value of one would belong in the whole part.')

chapter('How much can the three floors lose?','fraction_sum')
b(r'\left\lfloor\sum_{j=1}^{3}y_{ij}\right\rfloor','Start with the result we would get by adding first.\nThe summation sign means add the three terms.')
b(r'\left\lfloor\sum_{j=1}^{3}(w_{ij}+f_{ij})\right\rfloor','Replace each scaled share by its whole part\nplus its fractional part. Nothing has changed yet.')
b(r'\left\lfloor\sum_{j=1}^{3}w_{ij}+\sum_{j=1}^{3}f_{ij}\right\rfloor','Regroup the whole parts together\nand the fractional parts together.')
b(r'\sum_{j=1}^{3}w_{ij}+\left\lfloor\sum_{j=1}^{3}f_{ij}\right\rfloor','The sum of the w terms is an integer.\nMoving an integer outside a floor is exact.')
b(r'\lfloor9+2.4\rfloor=9+\lfloor2.4\rfloor=11','Here is the same rule with numbers.\nThe whole nine does not affect how 2.4 rounds down.')
b(r'0\le f_{i1}+f_{i2}+f_{i3}<3','There are three fractional parts, each smaller than one.\nTheir sum can approach three, but cannot reach it.','fraction_sum')
b(r'e:=\left\lfloor\sum_{j=1}^{3}f_{ij}\right\rfloor\in\{0,1,2\}','The floor of that sum can only be 0, 1, or 2.\nCall it e: the whole units lost by flooring separately.')

chapter('Adding two makes the remaining error nonnegative','correction')
b(r'F_{14}\!\left(\sum_{j=1}^{3}x_{ij}\right)=\sum_{j=1}^{3}F_{14}(x_{ij})+e','Returning to the original notation gives this exact equality.\nFor now, the share sum has not been reduced modulo 3329.',hold=10)
b(r'\sum_{j=1}^{3}F_{14}(x_{ij})=F_{14}\!\left(\sum_{j=1}^{3}x_{ij}\right)-e','Subtract e from both sides.\nThe separately transformed sum is too small by e.')
b(r'\sum_{j=1}^{3}F_{14}(x_{ij})+2=F_{14}\!\left(\sum_{j=1}^{3}x_{ij}\right)+(2-e)','Now add two to both sides.\nThe corrected estimate is above the true transform by 2 minus e.','correct',10)
b(r'\delta:=2-e','We give that remaining difference the name delta.\nIt is a quantity in our proof, not an extra input to PAMS.')
b(r'\begin{array}{c|ccc}e&0&1&2\\\hline\delta=2-e&2&1&0\end{array}','If we lost nothing, two remains. If we lost one, one remains.\nIf we lost two, the added two exactly replaces it.','cases',10)
b(r'\boxed{0\le\delta\le2}','PAMS need not know which loss occurred.\nAdding two guarantees a remaining difference between zero and two.')

chapter('Why reduction changes equality into congruence','modulo')
b(r'x_i=\left(\sum_{j=1}^{3}x_{ij}\right)\bmod3329','The original coefficient is the remainder of the share sum.\nModulo means keep that remainder.')
b(r'\sum_{j=1}^{3}x_{ij}=x_i+k\cdot3329,\qquad k\in\{0,1,2\}','Three canonical shares can cross 3329 at most twice.\nThe integer k counts how many full turns are removed.')
b(r'F_{14}(x_i+k\cdot3329)=\left\lfloor\frac{2^{14}x_i}{3329}+k\cdot2^{14}\right\rfloor','Substitute that unreduced sum into F.\nEach full turn of 3329 becomes a full turn of 16384.',hold=10)
b(r'F_{14}(x_i+k\cdot3329)=F_{14}(x_i)+k\cdot2^{14}','The added multiple of 16384 is an integer.\nIt comes straight outside the floor.','modulo')
b(r'\sum_{j=1}^{3}F_{14}(x_{ij})+2\equiv F_{14}(x_i)+\delta\pmod{2^{14}}','Congruent means the two sides have the same remainder.\nThe extra full turns disappear when we take that remainder.',hold=10)
b(r'Z_i=\left(F_{14}(x_i)-F_{14}(a_{c_i})+\delta\right)\bmod2^{14}','Subtract the same transformed starting boundary.\nThis gives the position Z in terms of the original coefficient.',hold=10)
b(r'\boxed{0\le\delta\le2}','Proof 1 is complete: the remaining difference\nis never negative and never greater than two.')

chapter('2. Is there room for a two-unit correction?','spacing')
b(r'x,\quad x+1','Neighboring coefficients are one unit apart\nbefore we transform them.')
b(r'F_{14}(x),\quad F_{14}(x+1)','After scaling and flooring, their separation is larger.\nWe need a guaranteed minimum, not an average.','spacing')
b(r'0\le\delta\le2','The corrected position can move upward by two.\nWatch that movement beside the next transformed value.','shift2')
b(r'F_{14}(x+1)-F_{14}(x)>2','Can the correction cross the comparison threshold?\nWe will first prove a spacing bound, then include the threshold.')
b(r'\Theta_{c_i}=\text{transformed interval width}-1','The threshold sits one unit before the next boundary.\nA four-unit gap will leave room for both adjustments.')

chapter('Derive the four-or-five-unit spacing','spacing')
b(r'F_{14}(x+1)-F_{14}(x)=\left\lfloor\frac{2^{14}(x+1)}{3329}\right\rfloor-\left\lfloor\frac{2^{14}x}{3329}\right\rfloor','Write both transforms using their definition.\nOnly the first numerator contains x plus one.',hold=10)
b(r'=\left\lfloor\frac{2^{14}x}{3329}+\frac{2^{14}}{3329}\right\rfloor-\left\lfloor\frac{2^{14}x}{3329}\right\rfloor','Distribute the multiplication in that numerator.\nIncreasing x by one adds the same fixed amount each time.',hold=10)
b(r'\frac{2^{14}}{3329}=\frac{16384}{3329}\approx4.9216','Before flooring, each step adds about 4.92.\nBut a rounded decimal is not enough for an exact proof.')
b(r'\frac{2^{14}}{3329}=4+r,\qquad r=\frac{3068}{3329},\qquad0<r<1','Write the exact ratio as four plus a fraction r.\nThat fraction is strictly between zero and one.')
b(r'y:=\frac{2^{14}x}{3329}','Use y as a shorter name for the scaled starting value.\nThis keeps the next lines easier to read.')
b(r'F_{14}(x+1)-F_{14}(x)=\lfloor y+4+r\rfloor-\lfloor y\rfloor','Substitute y and four plus r.\nWe are still calculating the same difference.')
b(r'=4+\lfloor y+r\rfloor-\lfloor y\rfloor','Move the whole four outside the floor.\nOnly the fractional addition r remains inside.')
b(r'\lfloor y+r\rfloor-\lfloor y\rfloor\in\{0,1\}','Adding less than one can cross at most one integer.\nThe floor either stays where it was or increases by one.','floor_step')
b(r'F_{14}(x+1)-F_{14}(x)\in\{4,5\}','Add the four back.\nThe total step must be exactly four or exactly five.','spacing')
b(r'\boxed{F_{14}(x+1)-F_{14}(x)\ge4>2\ge\delta}','Even the smaller step exceeds the largest correction.\nProof 3 will use that spare room at the interval boundary.','shift2')

chapter('What changes if we use thirteen bits?','thirteen')
b(r'F_{13}(x)=\left\lfloor\frac{2^{13}x}{3329}\right\rfloor','Thirteen bits would use 8192 positions\ninstead of 16384.')
b(r'\frac{8192}{3329}\approx2.46','One original step now adds only about 2.46\nbefore the floor is applied.')
b(r'F_{13}(1)-F_{13}(0)=2','A neighboring gap can be just two.\nThat is no larger than our worst-case correction.','thirteen')
b(r'F_{13}(1)-F_{13}(0)=2,\qquad F_{14}(1)-F_{14}(0)=4','The spacing argument we need works at fourteen bits.\nIt does not work with this thirteen-bit bound.')
b(r'F_{14}(x+1)-F_{14}(x)\ge4>2\ge\delta','This establishes enough separation for this construction.\nIt does not rule out every possible alternative thirteen-bit design.')

chapter('3. Prove that the comparison answers the right question','interval')
b(r'[Z_i<\Theta_{c_i}]=[\operatorname{Compress}_d(x_i)=c_i]','We have bounded the rounding error and the spacing.\nNow we must connect them to the actual compression interval.',hold=9)
b(r'q=3329,\qquad d=\text{number of bits per compressed coefficient}','Here q is 3329, the original modulus.\nThe bit width d determines how many compressed values there are.')
b(r'\operatorname{Compress}_d(x)=\left\lfloor\frac{2^d x}{q}+\frac12\right\rfloor\bmod2^d','Compression rounds the scaled coefficient to the nearest integer.\nThe last modulo makes the compressed values cyclic.',hold=9)
b(r'c_i-\frac12\le\frac{2^d x}{q}<c_i+\frac12','For a chosen unwrapped output, these are the rounding limits.\nThe lower edge is included; the upper edge is excluded.')
b(r'a_{c_i}=\left\lceil\frac{(2c_i-1)q}{2^{d+1}}\right\rceil\bmod q','Solve the lower limit for whole-number x.\nThe ceiling selects the first integer that is allowed.',hold=9)
b(r'a_{c_i+1}=\left\lceil\frac{(2c_i+1)q}{2^{d+1}}\right\rceil\bmod q','The next ceiling gives the first integer that is not allowed.\nThese boundaries also describe the interval that crosses zero.',hold=9)
b(r'x_i\text{ inside: pass}\qquad x_i\text{ outside: fail}','We must prove both directions.\nA test that accepts good values but also accepts bad ones is wrong.','inside_outside')

chapter('Measure from the start: s and L','interval')
b(r'a:=a_{c_i},\qquad q:=3329,\qquad M:=2^{14}=16384','These are shorter names for quantities we already use.\na is the start, q the original modulus, M the transformed modulus.')
b(r'd\in\{4,5,10,11\},\qquad0\le a,x_i<q','We use ML-KEM ciphertext compression widths.\nBoundaries and coefficients are represented from zero to q minus one.')
b(r's:=(x_i-a)\bmod q','s measures the forward distance from the interval start\nto the coefficient. Taking a remainder handles crossing zero.')
b(r'L:=(a_{c_i+1}-a)\bmod q,\qquad0<L<q','L measures the forward distance to the next boundary.\nThat is the length of the acceptable interval.')
b(r'd=5,\quad c_i=10:\quad a=989,\quad a_{11}=1093','For this interval, the first allowed integer is 989.\nThe first disallowed integer is 1093.')
b(r'x_i=1000:\quad s=1000-989=11,\quad L=1093-989=104','Shift the start to zero. The coefficient is eleven steps along;\nthe interval extends for 104 steps.','relative')
b(r'\operatorname{Compress}_d(x_i)=c_i\iff s<L','The double arrow means true exactly when.\nCompressing to the expected value is equivalent to being inside.')

chapter('An interval can cross zero','circle')
b(r'd=4,\quad c_i=0:\quad a_0=3225,\quad a_1=105','This interval starts near the end of the number circle.\nMoving forward takes us through zero.')
b(r'\{3225,\ldots,3328,0,\ldots,104\}','All these integers belong to the same interval.\n105 itself is the first value outside it.','around')
b(r'L=(105-3225)\bmod3329=-3120+3329=209','The ordinary subtraction is negative. Add one full turn\nto obtain the forward distance: 209.')
b(r'x_i=50:\quad s=(50-3225)\bmod3329=154','Starting at 3225, it takes 104 steps to reach zero\nand another 50 to reach this coefficient.','circle50')
b(r'154<209\quad\Longrightarrow\quad\operatorname{Compress}_4(50)=0','The coefficient has not reached the next boundary.\nIt is inside, even though its ordinary value is smaller than the start.')
b(r'x_i=200:\quad s=(200-3225)\bmod3329=304\ge209','Move farther around to 200. Its distance is now too large.\nThe same test correctly puts it outside.','circle200')

chapter('Why the fractional part of a matters','alpha')
b(r'x_i=(a+s)\bmod q;\qquad a+s<q\Rightarrow x_i=a+s','First consider a distance that does not cross zero.\nThen the coefficient is simply the start plus the distance.')
b(r'F_{14}(x_i)=\left\lfloor\frac{M(a+s)}q\right\rfloor=\left\lfloor\frac{Ma}q+\frac{Ms}q\right\rfloor','Scale the sum and distribute the multiplication.\nCan we floor these two pieces separately?',hold=9)
b(r'\lfloor20.8+5.4\rfloor=26,\qquad\lfloor20.8\rfloor+\lfloor5.4\rfloor=25','No. Here the two fractional parts together make another whole unit.\nFlooring them separately loses that unit.','alpha_combine')
b(r'F_{14}(a+s)\ne F_{14}(a)+F_{14}(s)\quad\text{in general}','So transformed distance is not always F applied to distance.\nThe fractional part at the starting boundary can matter.')
b(r'\alpha:=\frac{Ma}q-F_{14}(a),\qquad0\le\alpha<1','Call that starting fraction alpha.\nIt is the exact fractional part of the scaled boundary.')
b(r'\frac{Ma}q=F_{14}(a)+\alpha','We can now separate the start into a whole part\nand its preserved fraction. Neither part has been discarded.')

chapter('Give the transformed distance a name','g')
b(r'F_{14}(x_i)=\left\lfloor F_{14}(a)+\alpha+\frac{Ms}q\right\rfloor','Replace the scaled start by its whole part plus alpha.\nKeep all of this inside the same floor.')
b(r'F_{14}(x_i)=F_{14}(a)+\left\lfloor\frac{Ms}q+\alpha\right\rfloor','F of a is an integer, so it moves outside.\nAlpha must stay inside with the scaled distance.')
b(r'F_{14}(x_i)-F_{14}(a)=\left\lfloor\frac{Ms}q+\alpha\right\rfloor','Subtract F of a. What remains is the transformed distance\nfrom the starting boundary to the coefficient.')
b(r'\boxed{G(s):=\left\lfloor\frac{Ms}q+\alpha\right\rfloor}','We will use this expression repeatedly, so call it G of s.\nG includes the starting fraction that F of s alone would omit.','g')
b(r'\alpha:\ \text{fraction of the scaled start}\qquad\delta:\ \text{share-rounding difference}','Alpha and delta do different jobs. Alpha belongs to the boundary;\ndelta comes from flooring three shares separately.',hold=9)
b(r'0\le\alpha<1,\qquad\delta\in\{0,1,2\}','Alpha can be fractional. Delta is a whole-number difference.\nWe do not replace one with the other.')

chapter('Trace the identity without wraparound','ordinary')
b(r'x_i=a+s,\qquad a+s<q','Keep the no-wrap assumption visible.\nWe will trace the complete substitution one more time.')
b(r'F_{14}(x_i)=\left\lfloor\frac{M(a+s)}q\right\rfloor','Apply the definition of F to the coefficient.')
b(r'=\left\lfloor\frac{Ma}q+\frac{Ms}q\right\rfloor','Distribute M over the start and the distance.')
b(r'=\left\lfloor F_{14}(a)+\alpha+\frac{Ms}q\right\rfloor','Replace the scaled start with its integer part and alpha.')
b(r'=F_{14}(a)+\left\lfloor\frac{Ms}q+\alpha\right\rfloor=F_{14}(a)+G(s)','Take only the integer part outside the floor.\nThe remaining floor is exactly the definition of G.')
b(r'F_{14}(x_i)-F_{14}(a)=G(s)','Subtract the transformed start.\nFor this case we have an ordinary equality, before any modulo.')
b(r'a=989:\quad\alpha=\frac{1533}{3329},\quad s=11,\quad G(11)=54','In our numerical example, the distance eleven transforms to 54.\nThe starting fraction is included in that calculation.')
b(r'F_{14}(1000)-F_{14}(989)=4921-4867=54','Computing the two transforms separately gives the same distance.\nThis example checks the identity we just derived.','ordinary')

chapter('Trace the identity when the coefficient wraps','two_circles')
b(r'a+s\ge q,\quad0\le a,s<q\quad\Rightarrow\quad x_i=a+s-q','Both a and s are smaller than q. Their sum is below twice q,\nso exactly one subtraction of q is enough.')
b(r'F_{14}(x_i)=\left\lfloor\frac{M(a+s-q)}q\right\rfloor','Substitute the wrapped coefficient into the transform.')
b(r'=\left\lfloor\frac{Ma}q+\frac{Ms}q-M\right\rfloor','Distribute M. The term M times q divided by q is just M.\nA full original turn becomes a full transformed turn.','two_circles')
b(r'=\left\lfloor\frac{Ma}q+\frac{Ms}q\right\rfloor-M','M is an integer. Subtracting it inside the floor\nis the same as subtracting it afterward.')
b(r'=\left\lfloor F_{14}(a)+\alpha+\frac{Ms}q\right\rfloor-M','Use the same whole-part and fractional-part substitution\nthat worked in the no-wrap case.')
b(r'=F_{14}(a)+\left\lfloor\frac{Ms}q+\alpha\right\rfloor-M=F_{14}(a)+G(s)-M','Pull out the integer F of a.\nThe remaining floor is G, with one full turn subtracted.',hold=9)
b(r'F_{14}(x_i)-F_{14}(a)=G(s)-M','Subtract the transformed start.\nThe only difference from the earlier case is the extra minus M.')
b(r'(F_{14}(x_i)-F_{14}(a))\bmod M=G(s)\bmod M','Subtracting a full turn does not change the remainder.\nNow we must check that G already lies in the allowed range.')
b(r'0\le\frac{Ms}q+\alpha<\frac{M(q-1)}q+1','s is at most q minus one, and alpha is less than one.\nUse those two upper limits to bound the input to the floor.')
b(r'\frac{M(q-1)}q+1=M-\frac Mq+1<M\qquad(\tfrac Mq>1)','Expand the fraction. We subtract more than one and add one,\nso the result is still below M.')
b(r'0\le G(s)<M\quad\Rightarrow\quad\boxed{G(s)=(F_{14}(x_i)-F_{14}(a))\bmod M}','Taking the floor preserves nonnegativity and the upper bound.\nG is already the remainder. Both cases give the same identity.',hold=9)
b(r'x_i=50:\quad(246-15872)\bmod16384=758=G(154)','Here is the wrapped example. The negative difference\nbecomes the positive forward distance after one full turn is added.')

chapter('Z is distance plus the remaining rounding difference','z_distance')
b(r'Z_i=(F_{14}(x_i)-F_{14}(a)+\delta)\bmod M','Recall the result from Proof 1.\nIt describes the transformed difference plus delta.')
b(r'G(s)=(F_{14}(x_i)-F_{14}(a))\bmod M','The identity we just proved replaces the transformed difference\nby the corresponding forward distance.')
b(r'\boxed{Z_i=(G(s)+\delta)\bmod M}','Substitute G. Adding the same delta to congruent values\npreserves their remainder.','z_distance')
b(r'G(154)=758,\qquad0\le\delta\le2','For the wrapped example, the corrected distance\ncan be 758, 759, or 760.','z_shift')
b(r'\delta\text{ is used in the proof, not supplied to the circuit}','This describes the result of the share calculation.\nIt does not mean the implementation learns or reconstructs delta.')

chapter('The transformed interval width is G of L','threshold')
b(r'L=(a_{c_i+1}-a)\bmod q,\qquad a_{c_i+1}=(a+L)\bmod q','The next boundary is L steps forward from the start.\nIt follows the same distance rule as any coefficient.')
b(r'G(L)=(F_{14}(a_{c_i+1})-F_{14}(a))\bmod M','Use our distance identity with L in place of s.\nG of L is the transformed width of the interval.')
b(r'\Theta_{c_i}=(F_{14}(a_{c_i+1})-F_{14}(a)-1)\bmod M','Recall the definition of theta.\nIt subtracts one more unit than the transformed width.')
b(r'\Theta_{c_i}=(G(L)-1)\bmod M','Replace the boundary difference by G of L.')
b(r'G(0)=0,\quad L\ge1,\quad G(L)\ge4,\quad G(L)<M','A nonempty interval is at least one step long.\nThe same four-unit spacing argument applies with alpha included.')
b(r'\boxed{\Theta_{c_i}=G(L)-1}','Subtracting one cannot go negative or reach M.\nThe modulo therefore leaves this threshold unchanged.','threshold')
b(r'd=4,\ c_i=0:\quad G(209)=1028,\quad\Theta_0=1027','For our cyclic interval, the transformed width is 1028.\nThe comparison threshold is one less: 1027.')
b(r'\boxed{\begin{aligned}Z_i&=(G(s)+\delta)\bmod M\\\Theta_{c_i}&=G(L)-1\end{aligned}}','Both sides now use distances from the same start.\nNext we prove the spacing property of G carefully.',hold=9)

chapter('Why G increases by at least four','g_steps')
b(r'G(t)=\left\lfloor\frac{Mt}q+\alpha\right\rfloor','Increasing means a larger integer input gives a larger output.\nWe need that property for the distances s and L.')
b(r'G(t+1)-G(t)=\left\lfloor\frac{M(t+1)}q+\alpha\right\rfloor-\left\lfloor\frac{Mt}q+\alpha\right\rfloor','Subtract two neighboring outputs using the definition.\nThe same alpha appears in both.',hold=9)
b(r'=\left\lfloor\frac{Mt}q+\alpha+\frac Mq\right\rfloor-\left\lfloor\frac{Mt}q+\alpha\right\rfloor','Distribute the multiplication in the first floor.\nMoving one step still adds M divided by q.')
b(r'y:=\frac{Mt}q+\alpha,\qquad\frac Mq=4+r,\quad0<r<1','This time y includes alpha.\nThe extra fraction changes the starting value, not the step size.')
b(r'G(t+1)-G(t)=\lfloor y+4+r\rfloor-\lfloor y\rfloor','The calculation is now exactly the form used in Proof 2.')
b(r'=4+\lfloor y+r\rfloor-\lfloor y\rfloor\in\{4,5\}','Move out the four. The two remaining floors\ndiffer by either zero or one.','g_steps')
b(r'\boxed{G(t+1)-G(t)\ge4}','Every integer step increases G by at least four.\nRepeated steps preserve order, so G is strictly increasing.')

chapter('Look closely at the last acceptable position','edge')
b(r's<L\quad\Rightarrow\quad s\le L-1','s and L are integers. There is no integer between\nL minus one and L, so the last allowed position is L minus one.')
b(r'\text{last allowed: }L-1\qquad\text{first outside: }L','These two positions sit on opposite sides of the boundary.\nWe will track the last allowed one through the correction.','edge_original')
b(r'G(L)-G(L-1)\ge4','After transformation, the gap is at least four.\nThe diagram shows the smallest possible gap.','edge')
b(r'G(L-1)\le G(L)-4','Rearrange the spacing bound.\nThe last allowed value starts at least four units before the boundary.')
b(r'G(L-1)+\delta\le G(L)-2','Now add the largest possible correction: two.\nThe position still ends at least two units before the boundary.','edge_shift')
b(r'G(L)-2<G(L)-1=\Theta_{c_i}','Theta is just one unit before the boundary.\nThe corrected position remains strictly below it.','edge_threshold')
b(r'\boxed{G(L-1)+\delta<\Theta_{c_i}}','That strict inequality matters: equality would fail the test.\nEven the worst allowed position cannot reach equality.')
b(r'd=5,\ c_i=10:\quad G(103)+2=507+2=509<511','The ordinary example has a five-unit final gap.\nIts worst corrected position is 509, below the threshold 511.')

chapter('Every acceptable coefficient passes','edge')
b(r's<L\quad\Rightarrow\quad s\le L-1','Take any acceptable coefficient,\nnot just the last one in the interval.')
b(r'G(s)\le G(L-1)','Because G increases, any earlier input\nhas an output no larger than that last allowed output.')
b(r'G(L-1)\le G(L)-4\quad\Rightarrow\quad G(s)\le G(L)-4','Combine that ordering with the four-unit gap.\nEvery allowed output starts at least four units below the boundary.')
b(r'G(s)+\delta\le G(L)-4+\delta','Add the same delta to both sides.\nThis keeps the direction of the inequality.')
b(r'G(s)+\delta\le G(L)-4+2=G(L)-2','Delta is no larger than two.\nUsing two gives an upper bound for every possible correction.','edge_shift')
b(r'G(s)+\delta\le G(L)-2<G(L)-1=\Theta_{c_i}','Two units before the boundary is strictly below\none unit before it. The comparison therefore passes.','edge_threshold')
b(r'0\le G(s)+\delta<\Theta_{c_i}<M','This value is nonnegative and already smaller than M.\nTaking a remainder cannot change it.')
b(r'\boxed{s<L\ \Longrightarrow\ Z_i<\Theta_{c_i}}','Every acceptable coefficient passes,\nfor every remaining correction from zero through two.')

chapter('Every unacceptable coefficient must fail','outside')
b(r's\ge L','Now take any coefficient outside the acceptable interval.\nIts forward distance has reached or passed L.')
b(r'G(s)\ge G(L)','Since G increases, its transformed distance\nhas reached or passed the transformed boundary.')
b(r'\delta\ge0\quad\Rightarrow\quad G(s)+\delta\ge G(L)','The correction cannot move this value backward.\nIt either stays put or moves farther forward.','outside_shift')
b(r'G(L)=\Theta_{c_i}+1\quad\Rightarrow\quad G(s)+\delta>\Theta_{c_i}','The boundary is already one unit beyond theta.\nSo the unreduced value fails the comparison.')
b(r'Z_i=(G(s)+\delta)\bmod M','But Z is a remainder. Could a large failing value wrap\nto a small passing value? We must rule that out.')

chapter('Why the corrected distance cannot wrap again','no_wrap')
b(r'(M+1)\bmod M=1','This is the danger: a value beyond a full turn\ncan return to a small number. Our bound must prevent that.','danger')
b(r'0\le s\le q-1','A forward distance is at most q minus one.\nA full turn would have remainder zero.')
b(r'G(s)\le\left\lfloor\frac{M(q-1)}q+\alpha\right\rfloor','Replace s by its largest possible value.\nScaling by the positive ratio preserves the upper bound.')
b(r'G(s)<\frac{M(q-1)}q+1=M-\frac Mq+1','A floor never exceeds its input, and alpha is less than one.\nThat makes this upper bound strict.',hold=9)
b(r'\frac Mq>4\quad\Rightarrow\quad G(s)<M-3','Subtracting more than four, then adding one,\nleaves less than M minus three.')
b(r'G(s)\in\mathbb Z\quad\Rightarrow\quad G(s)\le M-4','G is a whole number. If it is strictly below M minus three,\nit can be at most M minus four.','no_wrap')
b(r'G(s)+\delta\le M-4+2=M-2<M','Even after adding the largest correction,\nwe remain below a full turn. There is no second wrap.','no_wrap_shift')
b(r'Z_i=G(s)+\delta','The modulo does nothing to this value.\nOur ordinary inequality really does describe Z.')
b(r'\boxed{s\ge L\ \Longrightarrow\ Z_i>\Theta_{c_i}\ \Longrightarrow\ Z_i\ge\Theta_{c_i}}','Every unacceptable coefficient fails the strict less-than test.\nIn fact, it is strictly above the threshold here.',hold=9)
b(r'x_i=200:\quad1496\le Z_i\le1498,\quad\Theta_0=1027','For the outside cyclic example, even the smallest possible Z\nis beyond the threshold. All three possible corrections fail.')

chapter('The two cases establish equivalence','equivalence')
b(r'\begin{aligned}s<L&\Rightarrow Z_i<\Theta_{c_i}\\s\ge L&\Rightarrow Z_i\ge\Theta_{c_i}\end{aligned}','Every integer distance falls into exactly one of these cases.\nThe comparison agrees in both.',hold=9)
b(r's<L\iff Z_i<\Theta_{c_i}','So a distance is inside exactly when the comparison passes.\nThis double arrow includes both directions.')
b(r'\operatorname{Compress}_d(x_i)=c_i\iff s<L','Recall how we obtained the interval: it is precisely\nthe set of coefficients that compress to the expected value.')
b(r'\begin{aligned}\operatorname{Compress}_d(x_i)=c_i&\iff s<L\\&\iff Z_i<\Theta_{c_i}\end{aligned}','Join the two equivalences.\nCompression, interval membership, and the PAMS test give one answer.','equivalence',10)
b(r'\boxed{[Z_i<\Theta_{c_i}]=[\operatorname{Compress}_d(x_i)=c_i]}','The brackets convert matching truth values to matching bits.\nThis is the comparison identity we set out to prove.',hold=12)

chapter('Three proofs, one coefficient test','roadmap')
b(r'\boxed{0\le\delta=2-e\le2}','First: separately flooring three shares loses at most two.\nAdding two leaves a small, nonnegative difference.','recap1')
b(r'\boxed{F_{14}(x+1)-F_{14}(x)\ge4>2\ge\delta}','Second: fourteen bits separate neighbors by at least four.\nThat leaves enough room for the rounding uncertainty.','recap2')
b(r'\boxed{s<L\iff Z_i<\Theta_{c_i}}','Third: measuring from the interval start handles both ordinary\nand cyclic intervals. Both the inside and outside cases are correct.','recap3')
b(r'\boxed{b^{(i)}=[Z_i<\Theta_{c_i}]=[\operatorname{Compress}_d(x_i)=c_i]}','PAMS can make the coefficient check from its arithmetic shares\nwithout requiring the implementation to reconstruct the unmasked value.',hold=12)
b(r'\text{Mathematical functional correctness}','This proves what the comparison computes under our assumptions.\nIt does not by itself prove a physical circuit resists side-channel attacks.')
b(r'\text{Next: Hardware Realization}','PAMS — Part 2: Mathematical Proofs\nNext we connect these equations to a masked hardware implementation.','end',10)

F={}
for ci,ch in enumerate(CHAPTERS,1):
    for bi,beat in enumerate(ch['beats'],1):
        key=f'p2_{ci:02}_{bi:02}';beat['key']=key;F[key]=beat['tex']

if __name__=='__main__':
    from pathlib import Path
    import subprocess,json,re,pymupdf
    from formulas import outline_svg_strokes
    root=Path(__file__).parent;assets=root/'assets/part2';assets.mkdir(exist_ok=True)
    colors={r'\alpha':'C59AFF',r'\delta':'FFD96A',r'\Theta_{c_i}':'FF7E8B','x_i':'67B5FF','x_{ij}':'67B5FF','a':'79DEA5','s':'69DAE3','L':'F4AD6D','G':'91D6C1','Z_i':'82B9FF'}
    pattern=re.compile(r'\\(?:text|operatorname|begin|end)\{[^}]*\}|\\Theta_\{c_i\}|\\alpha|\\delta|x_\{ij\}|x_i|Z_i|\\[A-Za-z]+|(?<![A-Za-z])[asLG](?![A-Za-z])')
    def colored(tex):
        return r'\color[HTML]{F1F5FC}'+pattern.sub(lambda m:r'\textcolor[HTML]{'+colors[m[0]]+'}{'+m[0]+'}' if m[0] in colors else m[0],tex)
    pre=r'\documentclass[multi=equationpage,border=2pt]{standalone}\usepackage{amsmath,amssymb,xcolor}\newenvironment{equationpage}{}{}\begin{document}'
    body='\n'.join(r'\begin{equationpage}$\displaystyle '+colored(t)+r'$\end{equationpage}' for t in F.values())
    (assets/'equations.tex').write_text(pre+body+r'\end{document}',encoding='utf8')
    subprocess.run([str(root/'tools/tectonic.exe'),str(assets/'equations.tex')],check=True)
    doc=pymupdf.open(assets/'equations.pdf');assert len(doc)==len(F)
    audit={}
    for key,page in zip(F,doc):
        svg,n=outline_svg_strokes(page.get_svg_image(text_as_path=True));audit[key]=n
        target=assets/(key+'.svg');temporary=target.with_suffix('.svg.tmp')
        temporary.write_text(svg,encoding='utf8');temporary.replace(target)
    (root/'qa/part2/stroke-audit.json').write_text(json.dumps(audit,indent=2))
    (root/'qa/part2/lesson.json').write_text(json.dumps(CHAPTERS,indent=2),encoding='utf8')
    print('Compiled',len(F),'equations across',len(CHAPTERS),'chapters')
